<style>
.publicity-toolbar{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:22px}.publicity-switch{display:inline-flex;background:#e5eff4;padding:4px;border-radius:30px;gap:4px}.publicity-switch a{padding:10px 22px;border-radius:24px;text-decoration:none;font-weight:800}.publicity-switch a[aria-current=page]{background:var(--brand);color:white}.publicity-section{margin:26px 0}.publicity-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.publicity-fields label{display:grid;gap:6px}.publicity-fields .wide{grid-column:1/-1}.publicity-slide-list{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:16px;margin:16px 0}.publicity-slide-list details{padding:18px}.publicity-slide-list summary{font-weight:800;cursor:pointer}.publicity-slide-list form{margin-top:18px}.publicity-note{color:var(--muted);font-size:14px}.publicity-screen{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:18px 0;border-bottom:1px solid var(--line)}.publicity-screen p{margin:5px 0}.publicity-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:16px}@media(max-width:700px){.publicity-fields{grid-template-columns:1fr}.publicity-screen{align-items:start;flex-direction:column}}
</style>
